const { Given, When, Then, After } = require('@cucumber/cucumber');
const { expect } = require('expect');

// ---------------------------------------------------------------------------
// Given
// ---------------------------------------------------------------------------

Given('the app is loaded', function () {
  // Already loaded by Before hook in world.js. No action needed.
});

Given('the todo list is empty', function () {
  // Verify the list is empty, then clear any localStorage leftovers
  const list = this.document.querySelector('.todo-list');
  expect(list.children.length).toBe(0);
  // Also clear localStorage to ensure clean state
  this.localStorage.clear();
});

// ---------------------------------------------------------------------------
// When — creating
// ---------------------------------------------------------------------------

When('I type {string} into the new todo input and press Enter', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
  input.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  input.dispatchEvent(
    new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true })
  );
});

When('I type {string} into the new todo input', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
  input.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

// ---------------------------------------------------------------------------
// When — toggling
// ---------------------------------------------------------------------------

When('I click the toggle checkbox on the todo', function () {
  const toggle = this.document.querySelector('.todo-list li .toggle');
  if (!toggle) throw new Error('No todo toggle found');
  toggle.click();
});

When('I click the toggle checkbox on {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const li of items) {
    const label = li.querySelector('label');
    if (label && label.textContent.trim() === title) {
      li.querySelector('.toggle').click();
      return;
    }
  }
  throw new Error(`No todo found with title "${title}"`);
});

When('I click the "Mark all as complete" toggle', function () {
  const toggle = this.document.getElementById('toggle-all');
  if (!toggle) throw new Error('No toggle-all checkbox found');
  toggle.click();
});

// ---------------------------------------------------------------------------
// When — destroying
// ---------------------------------------------------------------------------

When('I click the destroy button on the todo', function () {
  const btn = this.document.querySelector('.todo-list li .destroy');
  if (!btn) throw new Error('No destroy button found');
  // The destroy button is only visible on hover. Force click via dispatch.
  btn.click();
});

// ---------------------------------------------------------------------------
// When — editing
// ---------------------------------------------------------------------------

When('I double-click the todo label', function () {
  const label = this.document.querySelector('.todo-list li label');
  if (!label) throw new Error('No todo label found');
  label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
});

When('I type {string} into the edit input and press Enter', function (text) {
  const input = this.document.querySelector('.todo-list li .edit');
  if (!input) throw new Error('No edit input found');
  input.value = text;
  input.dispatchEvent(
    new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true })
  );
  input.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When('I type {string} into the edit input and blur', function (text) {
  const input = this.document.querySelector('.todo-list li .edit');
  if (!input) throw new Error('No edit input found');
  input.value = text;
  input.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  input.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
});

When('I type {string} into the edit input and press Escape', function (text) {
  const input = this.document.querySelector('.todo-list li .edit');
  if (!input) throw new Error('No edit input found');
  input.value = text;
  input.dispatchEvent(
    new this.window.KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, which: 27, bubbles: true })
  );
});

When('I clear the edit input and blur', function () {
  const input = this.document.querySelector('.todo-list li .edit');
  if (!input) throw new Error('No edit input found');
  input.value = '';
  input.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  input.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
});

// ---------------------------------------------------------------------------
// When — clearing completed
// ---------------------------------------------------------------------------

When('I click the "Clear completed" button', function () {
  const btn = this.document.querySelector('.clear-completed');
  if (!btn) throw new Error('No clear-completed button found');
  btn.click();
});

// ---------------------------------------------------------------------------
// When — routing
// ---------------------------------------------------------------------------

When('I navigate to {string}', function (hash) {
  this.navigate(hash);
});

When('I click the {string} filter link', function (name) {
  const links = this.document.querySelectorAll('.filters a');
  for (const a of links) {
    if (a.textContent.trim() === name) {
      a.click();
      return;
    }
  }
